import type { buildFixtureEnvelopes } from "./fixtures.js";
import type { buildGoalCatalog } from "./goal-catalog.js";

export function renderFixtureModule(
  fixtures: Awaited<ReturnType<typeof buildFixtureEnvelopes>>,
  goals: Awaited<ReturnType<typeof buildGoalCatalog>>,
): string {
  const fixturesBody = JSON.stringify(
    fixtures.map(({ id, label, envelope }) => ({ id, label, envelope })),
    null,
    2,
  );
  const goalsBody = JSON.stringify(goals, null, 2);
  return [
    "// Generated by extension/scripts/build.ts from the deterministic offline pipeline. Do not edit by hand.",
    "// Contains sanitized guidance envelopes only: no user facts, fact keys, rule ids, or raw model output.",
    `export const FIXTURE_ENVELOPES: readonly { readonly id: string; readonly label: string; readonly envelope: unknown }[] = ${fixturesBody};`,
    "",
    `export const GOAL_CATALOG: readonly { readonly goal: string; readonly sessionId: string; readonly questions: readonly { readonly id: string; readonly label: string; readonly options: readonly { readonly id: string; readonly label: string }[] }[]; readonly outcomes: readonly { readonly answers: Readonly<Record<string, string>>; readonly envelope: unknown }[] }[] = ${goalsBody};`,
    "",
  ].join("\n");
}
